INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist CSV immer durch Kommas getrennt?', 2, '[{"text": "Nein", "correct": true, "because": "Trennzeichen variabel"}, {"text": "Ja", "correct": false, "because": "Kann auch Semikolon sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit CSV?', 3, '[{"text": "Tabellarische Daten austauschen", "correct": true, "because": "Einfaches Format"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "UI gestalten", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat CSV?', 5, '[{"text": "Tabellenstruktur", "correct": true, "because": "Zeilen und Spalten"}, {"text": "Trennzeichen", "correct": true, "because": "Trennt Werte"}, {"text": "Hierarchische Daten", "correct": false, "because": "Flach, nicht verschachtelt"}, {"text": "Binärformat", "correct": false, "because": "Textbasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CSV ist textbasiert. b) Es unterstützt komplexe Datenstrukturen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "CSV ist einfach"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Export in CSV?', 4, '[{"text": "Trennzeichen", "correct": false, "because": "Definiert Struktur"}, {"text": "Datenkonsistenz", "correct": false, "because": "Sichert Lesbarkeit"}, {"text": "Farbschema", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob CSV nur für Tabellen ist?', 2, '[{"text": "Ja", "correct": true, "because": "Tabellarisches Format"}, {"text": "Nein", "correct": false, "because": "Hauptzweck ist Tabellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Zeichen wähle ich oft als Trennzeichen?', 3, '[{"text": "Komma", "correct": true, "because": "Standard in CSV"}, {"text": "Doppelpunkt", "correct": false, "because": "Seltener genutzt"}, {"text": "Pfeil", "correct": false, "because": "Kein Trennzeichen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind beim Import wichtig?', 5, '[{"text": "Trennzeichen erkennen", "correct": true, "because": "Struktur verstehen"}, {"text": "Daten validieren", "correct": true, "because": "Fehler vermeiden"}, {"text": "UI anpassen", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) CSV ist plattformübergreifend. b) Es ist für große Daten ungeeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "CSV ist skalierbar"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen CSV-Import?', 4, '[{"text": "Datenquelle", "correct": false, "because": "Liefert Inhalt"}, {"text": "Trennzeichen", "correct": false, "because": "Strukturiert Daten"}, {"text": "Grafiksoftware", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt CSV Kommentare?', 2, '[{"text": "Nein", "correct": true, "because": "Kein Standard dafür"}, {"text": "Ja", "correct": false, "because": "Nur inoffiziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet CSV?', 4, '[{"text": "Einfachheit", "correct": true, "because": "Leicht zu erstellen"}, {"text": "Kompatibilität", "correct": true, "because": "Weit unterstützt"}, {"text": "Verschlüsselung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass CSV nur für Excel ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Viele Tools nutzen es"}, {"text": "Ja", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Export?', 3, '[{"text": "Einheitliches Trennzeichen", "correct": true, "because": "Sichert Lesbarkeit"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Korrektheit zählt"}, {"text": "Designanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CSV ist leicht lesbar. b) Es ist hierarchisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "CSV ist flach"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es beim Import?', 5, '[{"text": "Falsches Trennzeichen", "correct": true, "because": "Verfälscht Daten"}, {"text": "Inkonsistente Zeilen", "correct": true, "because": "Fehlerhafte Struktur"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim CSV-Export unwichtig?', 3, '[{"text": "Spaltenanzahl", "correct": false, "because": "Definiert Struktur"}, {"text": "Trennzeichen", "correct": false, "because": "Trennt Werte"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann CSV Sonderzeichen enthalten?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Anführungszeichen"}, {"text": "Nein", "correct": false, "because": "Technisch möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob CSV für große Daten ideal ist?', 2, '[{"text": "Ja", "correct": true, "because": "Einfach und skalierbar"}, {"text": "Nein", "correct": false, "because": "Keine Einschränkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für den Import in Python?', 4, '[{"text": "csv.reader", "correct": true, "because": "Parst CSV korrekt"}, {"text": "json.parse", "correct": false, "because": "Für JSON"}, {"text": "xml.read", "correct": false, "because": "Für XML"}]');
